func (siw *ServerInterfaceWrapper) MarkNotificationRead(c *gin.Context) {

	var err error

	// ------------- Path parameter "id" -------------
	var id NotificationID

	err = runtime.BindStyledParameterWithOptions("simple", "id", c.Param("id"), &id, runtime.BindStyledParameterOptions{Explode: false, Required: true})
	if err != nil {
		siw.ErrorHandler(c, fmt.Errorf("Invalid format for parameter id: %w", err), http.StatusBadRequest)
		return
	}

	c.Set(BearerAuthScopes, []string{})

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.MarkNotificationRead(c, id)
}

// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/auth/me", wrapper.GetCurrentUser)
	router.POST(options.BaseURL+"/auth/refresh", wrapper.RefreshSession)
	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.GET(options.BaseURL+"/events", wrapper.StreamEvents)
	router.GET(options.BaseURL+"/health/live", wrapper.HealthLive)
	router.GET(options.BaseURL+"/health/ready", wrapper.HealthReady)
	router.GET(options.BaseURL+"/monitors", wrapper.ListMonitors)
	router.POST(options.BaseURL+"/monitors", wrapper.CreateMonitor)
	router.DELETE(options.BaseURL+"/monitors/:id", wrapper.DeleteMonitor)
	router.GET(options.BaseURL+"/monitors/:id", wrapper.GetMonitor)
	router.PATCH(options.BaseURL+"/monitors/:id", wrapper.UpdateMonitor)
	router.GET(options.BaseURL+"/monitors/:id/checks", wrapper.ListMonitorChecks)
	router.GET(options.BaseURL+"/monitors/:id/incidents", wrapper.ListMonitorIncidents)
	router.POST(options.BaseURL+"/monitors/:id/pause", wrapper.PauseMonitor)
	router.POST(options.BaseURL+"/monitors/:id/resume", wrapper.ResumeMonitor)
	router.GET(options.BaseURL+"/notifications", wrapper.ListNotifications)
	router.PATCH(options.BaseURL+"/notifications/:id/read", wrapper.MarkNotificationRead)
}

